package local.proskurnin.preview;
import android.os.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import org.json.*;
public class AssistantActivity extends VoiceActivity {
 JSONArray history=new JSONArray();LinearLayout conversation;ScrollView scroll;int generation=0;SpeechPlayback speech;Button soundButton,replayButton;Button[] lowerActions;boolean searchEnabled=true;boolean foreground=false,soundEnabled=true;String lastSpeechId="";
 // Automatic re-arming is disabled: this TV recognizer repeatedly returned no speech.
 void cancelAuto(){}
 boolean retryVoice(int error){return false;}

 void openSource(String url){
  android.net.Uri uri=android.net.Uri.parse(url);if(!("https".equals(uri.getScheme())||"http".equals(uri.getScheme()))||uri.getHost()==null||url.length()>2048){status.setText("Ссылка недоступна");return;}speech.stop();
  try{startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,uri));}
  catch(android.content.ActivityNotFoundException e){showSourceCode(url,uri.getHost());}
  catch(Exception e){status.setText("Не удалось открыть источник");}
 }
 void showSourceCode(String url,String host){
  try{
   io.nayuki.qrcodegen.QrCode qr=io.nayuki.qrcodegen.QrCode.encodeText(url,io.nayuki.qrcodegen.QrCode.Ecc.MEDIUM);int scale=Math.max(2,dp(260)/(qr.size+8)),size=(qr.size+8)*scale;
   android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(size,size,android.graphics.Bitmap.Config.RGB_565);bitmap.eraseColor(0xffffffff);android.graphics.Canvas canvas=new android.graphics.Canvas(bitmap);android.graphics.Paint paint=new android.graphics.Paint();paint.setColor(0xff000000);
   for(int y=0;y<qr.size;y++)for(int x=0;x<qr.size;x++)if(qr.getModule(x,y))canvas.drawRect((x+4)*scale,(y+4)*scale,(x+5)*scale,(y+5)*scale,paint);
   android.app.Dialog dialog=new android.app.Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(24),dp(20),dp(24),dp(20));content.setBackground(panel(0xff141e2c,0));TextView heading=label("Открыть источник на телефоне",24);content.addView(heading);TextView hint=label(host+" · Наведите камеру на QR-код",15);hint.setPadding(0,dp(6),0,dp(12));content.addView(hint);
   ImageView code=new ImageView(this);android.graphics.drawable.BitmapDrawable drawable=new android.graphics.drawable.BitmapDrawable(getResources(),bitmap);drawable.setFilterBitmap(false);code.setImageDrawable(drawable);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(size,size);cp.gravity=Gravity.CENTER_HORIZONTAL;content.addView(code,cp);
   TextView address=label(url,12);address.setMaxLines(2);address.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);address.setPadding(0,dp(12),0,dp(12));content.addView(address);Button close=button("Вернуться к ответу");content.addView(close,new LinearLayout.LayoutParams(-1,dp(42)));close.setOnClickListener(v->dialog.dismiss());dialog.setContentView(content);dialog.setOnDismissListener(d->{code.setImageDrawable(null);bitmap.recycle();});dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(dp(650),-2);close.requestFocus();
  }catch(Exception e){status.setText("Источник: "+url);}
 }
 void webMessage(JSONObject result,String reply){
  boolean searched=result.optBoolean("web_searched",false);message(searched?"AI · ВЕБ-ПОИСК":"AI · БЕЗ ВЕБ-ПОИСКА",reply,false);TextView body=(TextView)conversation.getChildAt(conversation.getChildCount()-1);
  android.text.SpannableString linked=new android.text.SpannableString(reply);JSONArray cites=result.optJSONArray("citations"),sources=result.optJSONArray("sources");
  if(cites!=null)for(int i=0;i<cites.length();i++){JSONObject c=cites.optJSONObject(i);if(c==null)continue;int start=c.optInt("start",-1),end=c.optInt("end",-1);final String url=c.optString("url");if(start>=0&&end>start&&end<=reply.length())linked.setSpan(new android.text.style.ClickableSpan(){public void onClick(View v){openSource(url);}},start,end,android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}
  body.setText(linked);body.setLinkTextColor(0xff9ecbff);body.setMovementMethod(android.text.method.LinkMovementMethod.getInstance());body.setHighlightColor(0xff526e94);
  Button previous=null,first=null;
  if(sources!=null)for(int i=0;i<sources.length();i++){JSONObject source=sources.optJSONObject(i);if(source==null)continue;final String url=source.optString("url");String host=android.net.Uri.parse(url).getHost();Button link=button("["+(i+1)+"] "+source.optString("title",host)+" · "+host);link.setTextSize(14);link.setSingleLine(true);link.setEllipsize(android.text.TextUtils.TruncateAt.END);link.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(38));lp.topMargin=dp(8);conversation.addView(link,lp);link.setOnClickListener(v->openSource(url));if(first==null){first=link;link.setNextFocusUpId(voiceButton.getId());}if(previous!=null){previous.setNextFocusDownId(link.getId());link.setNextFocusUpId(previous.getId());}previous=link;}
  if(first!=null){for(Button b:lowerActions)b.setNextFocusDownId(first.getId());}else if(searched){TextView note=label("Поиск выполнен, но ссылки не получены. Ответ требует проверки.",12);conversation.addView(note);}
 }
 public void onCreate(Bundle state){super.onCreate(state);if(!getSharedPreferences("preview",0).getBoolean("ai_enabled",true)){finish();return;}
  searchEnabled=getSharedPreferences("preview",0).getBoolean("assistant_web_search",true);getSharedPreferences("preview",0).edit().putBoolean("assistant_auto_talk",false).apply();soundEnabled=getSharedPreferences("preview",0).getBoolean("assistant_speech",true);speech=new SpeechPlayback(this,()->alive&&foreground&&soundEnabled&&!listening,value->speechState(value));
  LinearLayout root=base("Давайте поговорим","AI · ВАШ СОБЕСЕДНИК");addInput(root,"Задайте вопрос или продолжите разговор…");voiceButton=button("◉  Голос");Button send=button("Спросить"),clear=button("Новый диалог"),back=button("Назад");soundButton=button(soundEnabled?"Озвучка: вкл":"Озвучка: выкл");replayButton=button("Повторить");Button searchButton=button(searchEnabled?"Поиск: вкл":"Поиск: выкл");searchButton.setOnClickListener(v->{searchEnabled=!searchEnabled;getSharedPreferences("preview",0).edit().putBoolean("assistant_web_search",searchEnabled).apply();searchButton.setText(searchEnabled?"Поиск: вкл":"Поиск: выкл");toggleStyle(searchButton,searchEnabled);if(!busy&&!listening&&!speech.active)status.setText(searchEnabled?"Следующий ответ — с веб-поиском":"Следующий ответ — без веб-поиска; данные могут быть неактуальными");});lowerActions=new Button[]{voiceButton,send,searchButton,soundButton,replayButton,clear,back};addActions(root,voiceButton,send,searchButton,soundButton,replayButton,clear,back);toggleStyle(searchButton,searchEnabled);toggleStyle(soundButton,soundEnabled);soundButton.setOnClickListener(v->{soundEnabled=!soundEnabled;getSharedPreferences("preview",0).edit().putBoolean("assistant_speech",soundEnabled).apply();soundButton.setText(soundEnabled?"Озвучка: вкл":"Озвучка: выкл");toggleStyle(soundButton,soundEnabled);if(!soundEnabled)speech.stop();});replayButton.setOnClickListener(v->{if(speech.active){speech.stop();return;}if(!soundEnabled){status.setText("Сначала включите озвучку");return;}if(!lastSpeechId.isEmpty()&&!listening&&!busy)speech.play(lastSpeechId);else status.setText("Сначала задайте вопрос и дождитесь ответа");});voiceButton.setOnClickListener(v->voice());send.setOnClickListener(v->submit());clear.setOnClickListener(v->{generation++;busy=false;speech.stop();lastSpeechId="";stopVoice();history=new JSONArray();conversation.removeAllViews();input.setText("");status.setText("Диалог очищен. Задайте новый вопрос.");});back.setOnClickListener(v->finish());
  scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setId(View.generateViewId());scroll.setFocusable(true);scroll.setBackground(panel(0xff141e2c,0));conversation=new LinearLayout(this);conversation.setOrientation(1);conversation.setPadding(dp(24),dp(18),dp(24),dp(18));scroll.addView(conversation);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(Button b:lowerActions)b.setNextFocusDownId(scroll.getId());scroll.setNextFocusUpId(voiceButton.getId());TextView foot=label("Голос создан AI · История до закрытия экрана · Поиск — по переключателю · AI требует интернет · AI может ошибаться",11);foot.setTextColor(0xff71839c);foot.setPadding(0,dp(10),0,0);root.addView(foot);status.setText("Спросите о том, что интересно. Можно уточнять предыдущий ответ.");message("AI", "Объясню сложное простыми словами, помогу с идеей или отвечу на вопрос.",false);voiceButton.requestFocus();
 }
 void message(String who,String text,boolean user){TextView tag=label(who,11);tag.setTextColor(user?0xff9ab7df:0xff8fbaa9);tag.setPadding(0,dp(10),0,dp(7));conversation.addView(tag);TextView body=label(text,user?18:21);body.setTypeface(Typeface.create("sans-serif-light",0));body.setLineSpacing(dp(4),1);conversation.addView(body);scroll.post(()->scroll.smoothScrollTo(0,conversation.getHeight()));}
 JSONArray boundedHistory()throws Exception{JSONArray result=new JSONArray();int start=Math.max(0,history.length()-6);while(start<history.length()){int count=0;for(int i=start;i<history.length();i++)count+=history.getJSONObject(i).getString("content").length();if(count<=4000)break;start+=2;}for(int i=start;i<history.length();i++)result.put(history.getJSONObject(i));return result;}
 void submit(){if(busy)return;speech.stop();if(listening)stopVoice();final String query=input.getText().toString().trim();if(query.length()<2||query.length()>800){status.setText("Задайте вопрос от 2 до 800 символов");return;}final JSONObject body;try{body=new JSONObject().put("query",query).put("history",boundedHistory()).put("web_search",searchEnabled);}catch(Exception e){status.setText("Не удалось подготовить вопрос");return;}busy=true;final int token=++generation;status.setText(searchEnabled?"Ищу источники и готовлю ответ…":"Готовлю ответ без веб-поиска…");message("ВЫ",query,true);
  new Thread(()->{String answer=null,error=null,speechId="";JSONObject result=null;try{result=ApiClient.request(this,"ai/chat",body);answer=result.getString("answer");speechId=result.optString("speech_id","");}catch(Exception e){error=ApiClient.message(e);}final String reply=answer,problem=error,spoken=speechId;final JSONObject response=result;handler.post(()->{if(!alive||generation!=token)return;busy=false;if(problem!=null){status.setText(problem);return;}try{history.put(new JSONObject().put("role","user").put("content",query));history.put(new JSONObject().put("role","assistant").put("content",reply.substring(0,Math.min(1200,reply.length()))));history=boundedHistory();}catch(Exception ignored){}webMessage(response,reply);input.setText("");status.setText("Нажмите «Голос», чтобы уточнить или задать следующий вопрос.");voiceButton.requestFocus();lastSpeechId=spoken;if(foreground&&soundEnabled&&!lastSpeechId.isEmpty())speech.play(lastSpeechId);});},"ai-dialog").start();
 }
 void speechState(String value){if("idle".equals(value))cancelAuto();if(replayButton==null)return;replayButton.setText(speech!=null&&speech.active?"Стоп":"Повторить");if(status==null||listening||busy)return;if("loading".equals(value))status.setText("Готовлю голосовой ответ…");else if("playing".equals(value))status.setText("Говорит AI · Back или «Стоп» — остановить");else if("error".equals(value))status.setText("Озвучка недоступна. Ответ можно прочитать или повторить позже.");else if("expired".equals(value))status.setText("Время повтора истекло. Задайте вопрос ещё раз.");else if("focus".equals(value))status.setText("Звук занят другим приложением. Ответ остаётся на экране.");else if(foreground)status.setText("Нажмите «Голос», чтобы продолжить разговор.");}
 void voice(){cancelAuto();if(speech!=null)speech.stop();super.voice();}
 public void onBackPressed(){cancelAuto();if(speech!=null&&speech.active){speech.stop();return;}super.onBackPressed();}
 protected void onResume(){foreground=true;super.onResume();}
 protected void onPause(){foreground=false;cancelAuto();if(speech!=null)speech.stop();super.onPause();}
 protected void onDestroy(){cancelAuto();generation++;history=new JSONArray();if(speech!=null)speech.close();super.onDestroy();}
}
